package com.campuspulse.service.impl;
import com.campuspulse.service.*;import com.campuspulse.entity.*;import com.campuspulse.enums.*;import com.campuspulse.repository.*;import com.campuspulse.dto.request.Requests;import com.campuspulse.dto.response.Responses;import com.campuspulse.exception.ApiException;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ComplaintServiceImpl implements ComplaintService{
private final ComplaintRepository complaints;private final ComplaintHistoryRepository histories;private final ComplaintAssignmentRepository assignments;private final UserRepository users;private final AuthService auth;private final ClassifierService classifier;
public ComplaintServiceImpl(ComplaintRepository complaints,ComplaintHistoryRepository histories,ComplaintAssignmentRepository assignments,UserRepository users,AuthService auth,ClassifierService classifier){this.complaints=complaints;this.histories=histories;this.assignments=assignments;this.users=users;this.auth=auth;this.classifier=classifier;}
private Complaint find(Long id){return complaints.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Complaint not found"));}
private void admin(){if(auth.current().role!=Role.ADMIN)throw new ApiException(HttpStatus.FORBIDDEN,"Admin access required");}
private void staff(){if(auth.current().role!=Role.STAFF)throw new ApiException(HttpStatus.FORBIDDEN,"Staff access required");}
private void permitted(Complaint c){User u=auth.current();if(u.role==Role.ADMIN||c.student.id.equals(u.id))return;if(u.role==Role.STAFF&&assignments.findFirstByComplaintIdOrderByAssignedAtDesc(c.id).map(a->a.staff.id.equals(u.id)).orElse(false))return;throw new ApiException(HttpStatus.FORBIDDEN,"You cannot access this complaint");}
private Responses.ComplaintView view(Complaint c){String staffName=assignments.findFirstByComplaintIdOrderByAssignedAtDesc(c.id).map(a->a.staff.name).orElse(null);return new Responses.ComplaintView(c.id,c.title,c.description,c.location,c.category,c.priority,c.status,c.aiExplanation,c.student.name,staffName,c.createdAt,c.updatedAt);}
private void log(Complaint c,String note){ComplaintHistory h=new ComplaintHistory();h.complaint=c;h.actor=auth.current();h.status=c.status;h.note=note;histories.save(h);}
@Transactional public Responses.ComplaintView create(Requests.CreateComplaint r){if(auth.current().role!=Role.STUDENT)throw new ApiException(HttpStatus.FORBIDDEN,"Only students can report complaints");var ai=classifier.analyze(r.title(),r.description());Complaint c=new Complaint();c.title=r.title().trim();c.description=r.description().trim();c.location=r.location().trim();c.student=auth.current();c.category=ai.category();c.priority=ai.priority();c.aiExplanation=ai.explanation();complaints.save(c);log(c,"Complaint submitted");return view(c);}
@Transactional(readOnly=true) public Page<Responses.ComplaintView> list(String scope,String search,String status,int page,int size){User u=auth.current();if(page<0||size<1||size>100)throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid pagination");if(scope.equals("admin")&&u.role!=Role.ADMIN||scope.equals("staff")&&u.role!=Role.STAFF||scope.equals("mine")&&u.role!=Role.STUDENT)throw new ApiException(HttpStatus.FORBIDDEN,"Access denied");String term=search==null?"":search.toLowerCase(Locale.ROOT);Status filter=null;try{if(status!=null&&!status.isBlank())filter=Status.valueOf(status);}catch(Exception e){throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid status");}final Status selected=filter;List<Complaint> all;if(scope.equals("staff")){var ids=assignments.findByStaffId(u.id,PageRequest.of(0,10000)).stream().map(a->a.complaint.id).collect(java.util.stream.Collectors.toSet());all=complaints.findAll().stream().filter(c->ids.contains(c.id)&&assignments.findFirstByComplaintIdOrderByAssignedAtDesc(c.id).map(a->a.staff.id.equals(u.id)).orElse(false)).toList();}else if(scope.equals("mine"))all=complaints.findAll().stream().filter(c->c.student.id.equals(u.id)).toList();else all=complaints.findAll();var filtered=all.stream().filter(c->(selected==null||c.status==selected)&&(c.title.toLowerCase(Locale.ROOT).contains(term)||c.description.toLowerCase(Locale.ROOT).contains(term))).sorted(Comparator.comparing((Complaint c)->c.createdAt).reversed()).toList();int from=Math.min(page*size,filtered.size());int to=Math.min(from+size,filtered.size());return new PageImpl<>(filtered.subList(from,to).stream().map(this::view).toList(),PageRequest.of(page,size),filtered.size());}
@Transactional(readOnly=true) public Responses.ComplaintView get(Long id){Complaint c=find(id);permitted(c);return view(c);}
@Transactional(readOnly=true) public List<Responses.HistoryView> history(Long id){Complaint c=find(id);permitted(c);return histories.findByComplaintIdOrderByCreatedAtAsc(id).stream().map(Responses.HistoryView::of).toList();}
private void require(Complaint c,Status... allowed){if(!Arrays.asList(allowed).contains(c.status))throw new ApiException(HttpStatus.CONFLICT,"Invalid status transition from "+c.status);}
@Transactional public Responses.ComplaintView review(Long id){admin();Complaint c=find(id);require(c,Status.SUBMITTED);c.status=Status.UNDER_REVIEW;complaints.save(c);log(c,"Under admin review");return view(c);}
@Transactional public Responses.ComplaintView reject(Long id,String note){admin();Complaint c=find(id);require(c,Status.SUBMITTED,Status.UNDER_REVIEW);c.status=Status.REJECTED;complaints.save(c);log(c,note);return view(c);}
@Transactional public Responses.ComplaintView assign(Long id,Long staffId){admin();Complaint c=find(id);require(c,Status.UNDER_REVIEW,Status.ASSIGNED);User s=users.findById(staffId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Staff not found"));if(s.role!=Role.STAFF)throw new ApiException(HttpStatus.BAD_REQUEST,"Selected user is not staff");ComplaintAssignment a=new ComplaintAssignment();a.complaint=c;a.staff=s;a.assignedBy=auth.current();assignments.save(a);c.status=Status.ASSIGNED;complaints.save(c);log(c,"Assigned to "+s.name);return view(c);}
@Transactional public Responses.ComplaintView priority(Long id,Priority p){admin();Complaint c=find(id);if(c.status==Status.RESOLVED||c.status==Status.REJECTED)throw new ApiException(HttpStatus.CONFLICT,"Closed complaint");c.priority=p;complaints.save(c);log(c,"Priority changed to "+p);return view(c);}
@Transactional public Responses.ComplaintView progress(Long id,Status next,String note){staff();Complaint c=find(id);permitted(c);if(c.status==Status.ASSIGNED&&next==Status.IN_PROGRESS||c.status==Status.IN_PROGRESS&&next==Status.RESOLVED){c.status=next;complaints.save(c);log(c,note);return view(c);}throw new ApiException(HttpStatus.CONFLICT,"Invalid status transition");}
}
